const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
const supplied = headers['x-kiazop-webhook-secret'] || headers['X-Kiazop-Webhook-Secret'];
const expected = $env.N8N_FORWARD_SECRET;
if (!expected || !supplied || supplied !== expected) {
  throw new Error('Webhook recusado: segredo ausente ou inválido. Configure N8N_FORWARD_SECRET no n8n e na Vercel.');
}
const payload = item.json.body ?? item.json;
const value = payload?.entry?.[0]?.changes?.[0]?.value;
const message = value?.messages?.[0];
if (!message || message.type !== 'text' || !message.text?.body) {
  return [{ json: { skip: true, reason: 'Evento sem mensagem de texto recebida.' } }];
}
const from = message.from;
const phoneNumberId = value?.metadata?.phone_number_id || $env.WHATSAPP_PHONE_NUMBER_ID;
const incoming = message.text.body.trim();
let reply = 'Olá! Bem-vindo à KIAZOP LIVROS 📚\\n\\nResponde com uma opção:\\n1 — Ver catálogo\\n2 — Categorias de livros\\n3 — Como comprar\\n4 — Falar com atendimento';
const normalized = incoming.normalize('NFD').replace(/[\\u0300-\\u036f]/g, '').toLowerCase();
if (['1', 'catalogo', 'livros'].includes(normalized)) reply = '📚 KIAZOP LIVROS\\nO nosso catálogo está a ser atualizado. Diz-nos o título ou tema do livro que procuras e a equipa confirma a disponibilidade.';
else if (['2', 'categoria', 'categorias'].includes(normalized)) reply = '📖 Que tipo de livro procuras?\\n• Desenvolvimento pessoal\\n• Negócios e finanças\\n• Educação\\n• Fé e estudos bíblicos\\nEscreve o tema pretendido.';
else if (['3', 'comprar', 'pagamento'].includes(normalized)) reply = '🛒 Para consultar disponibilidade e condições de compra, envia o título do livro pretendido. Não envies dados bancários nem palavras-passe por WhatsApp.';
else if (['4', 'atendimento', 'humano', 'pessoa'].includes(normalized)) reply = '👋 Atendimento KIAZOP LIVROS: https://wa.me/244942739225\\nEscreve a tua dúvida e a equipa dará seguimento.';
return [{ json: { skip: false, from, phoneNumberId, reply, incomingMessageId: message.id } }];
